    "codigo": "// notificationService.js
const MAX_RETRIES = 3;

async function withRetryAndLogs(label, sendFn) {
  const startTime = Date.now();
  let lastError;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    console.log(`[${label}] Tentativa ${attempt}/${MAX_RETRIES} — iniciando envio`);
    try {
      await sendFn();
      const elapsed = Date.now() - startTime;
      console.log(`[${label}] Sucesso após ${elapsed}ms`);
      return;
    } catch (err) {
      lastError = err;
      console.error(`[${label}] Falha na tentativa ${attempt}: ${err.message}`);
    }
  }

  throw lastError;
}

async function sendEmail(to, subject, body) {
  await withRetryAndLogs('Email', () => emailApi.send({ to, subject, body }));
}

async function sendSms(phoneNumber, text) {
  await withRetryAndLogs('SMS', () => smsApi.send({ phoneNumber, text }));
}

async function sendPushNotification(deviceToken, title, message) {
  await withRetryAndLogs('Push', () => pushApi.send({ deviceToken, title, message }));
}

module.exports = { sendEmail, sendSms, sendPushNotification };
